     7	
     8	export type PxcMetaCellProps = {
     9	  label: string;
    10	  title?: string;
    11	  children?: React.ReactNode;
    12	  /** Last cell in a row — no right border */
    13	  lastInRow?: boolean;
    14	  fullWidth?: boolean;
    15	};
    16	
    17	/** Portfolio-profile-style label | value cell (Tailwind utilities only). */
    18	export function PxcMetaCell(props: PxcMetaCellProps): React.ReactElement {
