/**
 * Sync snapshot from Overview/table click seed — used for first paint so the
 * profile is not a blank white shell while column-config / TaskUsers await.
 */
const readPxcSeedPaint = (): { header: any | null; tree: any[] } => {
  const qid = readPxcQueryId();
  if (!qid) return { header: null, tree: [] };
  const seed = getPxcSeed(qid);
  if (!seed || !seedMatchesId(seed, qid)) return { header: null, tree: [] };
  const header = {
    ...seed,
    Id: seed.Id ?? seed.ID ?? Number(qid),
    ID: seed.ID ?? seed.Id ?? Number(qid),
    TaskID: seed.TaskID || seed.PortfolioStructureID,
  };
  let tree: any[] = [];
  if (Array.isArray(seed.subRows) && seed.subRows.length > 0) {
    try {
      tree = rehomeOrphanAwtUnderParentTasks(clonePxcSeedRow(seed.subRows));
    } catch {
      tree = [];
    }
  }
  return { header, tree };
};

/** Flatten every node in a PXC seed tree (project + descendants). */
const flattenPxcSeedTreeNodes = (root: any): any[] => {
  const out: any[] = [];
  const walk = (node: any) => {
    if (!node) return;
    out.push(node);
    (Array.isArray(node.subRows) ? node.subRows : []).forEach(walk);
  };
  walk(root);
  return out;
};

/** Site-task rows embedded in the seed tree — no shared-task store / IndexedDB. */
const extractSiteTasksFromPxcTree = (roots: any[] | any): any[] => {
  const list = Array.isArray(roots) ? roots : roots ? [roots] : [];
  const out: any[] = [];
  const seen = new Set<number>();
  const walk = (nodes: any[]) => {
    if (!Array.isArray(nodes)) return;
    for (const n of nodes) {
      if (!n) continue;
      const id = Number(n?.Id ?? n?.ID);
      const isSiteTask =
        n?.TaskType != null ||
        n?.TaskTypeId != null ||
        (n?.siteType &&
          String(n.siteType).toLowerCase() !== 'master tasks');
      if (isSiteTask && id && !Number.isNaN(id) && !seen.has(id)) {
        seen.add(id);
        out.push({ ...n, subRows: undefined, isTaskPushed: false });
      }
      if (Array.isArray(n.subRows) && n.subRows.length) {
        walk(n.subRows);
      }
    }
  };
  walk(list);
  return out;
};

const clonePxcSeedRow = (row: any): any => {
  if (!row) return row;
  try {
    if (typeof (globalThis as any).structuredClone === 'function') {
      return (globalThis as any).structuredClone(row);
    }
  } catch {
    /* fall through */
  }
  try {
    return JSON.parse(JSON.stringify(row));
  } catch {
    return row;
  }
};

