const bindPxcProfileFromSeed = async (pxcSeed: any): Promise<boolean> => {
  if (!applyPxcSeedBindingSync(pxcSeed)) {
    return false;
  }
  await applyPxcSeedBindingAsync(pxcSeed);
  return stillLive();
};

const syncPxcTaskUsers = async (): Promise<void> => {
  const prefetchedUsers = Array.isArray(props?.TaskUser) ? props.TaskUser : [];
  if (prefetchedUsers.length > 0) {
    AllUser = prefetchedUsers.filter((i: any) => i.IsActive == 1);
    AllUser.forEach((user: any) => {
      if (user?.ItemType == 'Group') {
        getChilds(user, AllUser);
      }
    });
    CurrentUserData = AllUser?.find((user: any) => {
      if (
        AllListId?.Context?.pageContext?.legacyPageContext?.userId ==
        user?.AssingedToUser?.Id
      ) {
        return true;
      }
    });
    setAllTaskUsers(AllUser);
    return;
  }
  AllUser = await loadTaskUsers();
  if (!stillLive()) return;
  AllUser = AllUser.filter((i: any) => i.IsActive == 1);
  AllUser.forEach((user: any) => {
    if (user?.ItemType == 'Group') {
      getChilds(user, AllUser);
    }
  });
  setAllTaskUsers(AllUser);
};

