const applyPxcSeedBindingSync = (pxcSeed: any): boolean => {
  hydratePxcTaskUsersFromProps();

  const projectId = readPxcQueryId();
  if (projectId) {
    QueryId = projectId;
  }

  if (
    !QueryId ||
    !pxcSeed ||
    !seedMatchesId(pxcSeed, QueryId)
  ) {
    return false;
  }

  loadAllflatPXC = [];
  const projectItem = clonePxcSeedRow(pxcSeed);
  projectItem.__fromPxcSeed = true;
  projectItem.AssignedTo = projectItem.AssignedTo || [];
  projectItem.TeamMembers = projectItem.TeamMembers || [];
  projectItem.TaskCategories = projectItem.TaskCategories || [];
  projectItem.Portfolios = projectItem.Portfolios || [];
  projectItem.siteUrl = props?.siteUrl || projectItem.siteUrl;
  projectItem.listId = AllListId?.MasterTaskListID || projectItem.listId;
  projectItem.Id = projectItem.Id ?? projectItem.ID ?? Number(QueryId);
  projectItem.ID = projectItem.ID ?? projectItem.Id ?? Number(QueryId);
  projectItem.TaskID = projectItem.PortfolioStructureID || projectItem.TaskID || '';

  if (projectItem?.DueDate === '') {
    projectItem.DueDate = null;
  }
  if (projectItem?.DueDate != undefined && projectItem?.DueDate !== null) {
    const due = Moment(projectItem.DueDate);
    projectItem.DisplayDueDate = due.isValid() ? due.format('DD/MM/YYYY') : '';
  } else {
    projectItem.DisplayDueDate = '';
  }
  if (
    projectItem.PercentComplete != null &&
    !isNaN(Number(projectItem.PercentComplete))
  ) {
    projectItem.PercentComplete = Number(projectItem.PercentComplete).toFixed(0);
  }

  const rawTree = Array.isArray(projectItem.subRows) ? projectItem.subRows : [];
  const nestedSeed =
    rawTree.length > 0
      ? rehomeOrphanAwtUnderParentTasks(clonePxcSeedRow(rawTree))
      : [];

  projectData = projectItem;
  allBackupSprintAndTask = nestedSeed;
  backupTableData = nestedSeed;
  renderData = nestedSeed;

  AllFlatProject = flattenPxcSeedTreeNodes(projectItem);
  ancestorLookupList = AllFlatProject;
  AllMasterTasks = AllFlatProject;
  masterTasksUngroupedData = globalCommon.deepCopy(AllFlatProject);
  backupMasterTaskData = globalCommon.deepCopy(AllFlatProject);
  backupMasterTaskData.forEach((item: any, index: number) => {
    item.uniqueID = parseInt(`${index + 1}`);
  });

  MasterListData = [
    ...(Array.isArray(projectItem.taggedPortfolios) ? projectItem.taggedPortfolios : []),
    ...(Array.isArray(projectItem.Portfolios) ? projectItem.Portfolios : []),
    ...AllFlatProject,
  ];
  const seenSeed = new Set<number | string>();
  MasterListData = MasterListData.filter((item: any) => {
    const id = item?.Id ?? item?.ID;
    if (id == null || seenSeed.has(id)) return false;
    seenSeed.add(id);
    return true;
  });

  const taskRoots = nestedSeed.length > 0 ? nestedSeed : AllFlatProject;
  AllSitesAllTasks = extractSiteTasksFromPxcTree(taskRoots);
  AllSitesAllTasks.forEach((task: any) => {
    task.isTaskPushed = false;
    const pc = Number(task.PercentComplete);
    if (!Number.isNaN(pc) && pc <= 1) {
      task.PercentComplete = Math.round(pc * 100);
    }
  });
  AllSiteTasksForRestrcture = globalCommon.deepCopy(AllSitesAllTasks);
  backupTasksData = globalCommon.deepCopy(AllSitesAllTasks);

  setPageLoader(false);
  setMasterdata(projectItem);
  setProjectTitle(projectItem?.Title);
  setProjectTableData(nestedSeed);
  setWorkingTodayFiltered(false);
  setclickFlatView(false);

  if (projectItem?.Portfolios?.length > 0) {
    smartPortfoliosData = projectItem.Portfolios;
  }

  applyTeamCompositionFromSeed(projectItem);

  pxcProfileRouteBoundProjectId = String(QueryId);
  return true;
};

const applyPxcSeedBindingAsync = async (pxcSeed: any): Promise<void> => {
  if (!pxcSeed || !QueryId || !seedMatchesId(pxcSeed, QueryId)) {
    return;
  }

  try {
    setPxcSeed(Number(QueryId), {
      ...clonePxcSeedRow(pxcSeed),
      subRows: backupTableData,
    });
  } catch {
    /* ignore */
  }

  const projectItem = masterdataRef.current;
  if (projectItem?.PortfolioStructureID && projectItem?.Title) {
    document.title = `${projectItem.PortfolioStructureID}-${projectItem.Title}`;
  }

  // Seed paint skips LoadAllSiteTasks nest/count — fill Showing from painted tree.
  if (stillLive() && Array.isArray(backupTableData)) {
    await refreshPxcShowingCountsRef.current(backupTableData);
  }
};

